algorithms.pseudocode:
best = None
for order in permutations(0..n-1):
  value = sum of W[order[p]][order[q]] over p < q
  if best is None or value > best: best, best_order = value, order
return (best, best_order)

best[{}] = 0
for S = 0 .. 2^n - 1 (as integers, so subsets come first):
  for v not in S:
    gain = sum of W[v][u] over u not in S + {v}
    best[S | {v}] = max(best[S | {v}], best[S] + gain)   (remember the maximising v)
return best[all] and the order rebuilt from the remembered elements
